import{openAuditPage,pause}from'/workspace/trading101/docs/adsense-2026-10-22/browser-session.mjs';import{mkdirSync,writeFileSync,readFileSync,existsSync}from'node:fs';import assert from'node:assert/strict';
const[origin,sha,stage,port,theme]=process.argv.slice(2),root='/workspace/trading101/docs/adsense-2026-10-22/evidence/',folder=root+'quote-input-'+stage+'-20261030',receipt=root+'QUOTE-INPUT-'+stage.toUpperCase()+'-20261030.json';mkdirSync(folder,{recursive:true});const p=await openAuditPage('about:blank',Number(port)),rows=existsSync(receipt)?JSON.parse(readFileSync(receipt)).rows:[],errors=[],blocked=[];let failure=null;
p.onEvent(m=>{if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);if(m.method==='Fetch.requestPaused'){const{requestId,request}=m.params,u=new URL(request.url),safe=['GET','HEAD','OPTIONS'].includes(request.method)||(request.method==='POST'&&u.pathname==='/rest/v1/rpc/get_published_course_catalog');if(!safe)blocked.push({method:request.method,path:u.pathname});p.send(safe?'Fetch.continueRequest':'Fetch.failRequest',safe?{requestId}:{requestId,errorReason:'Aborted'}).catch(()=>{});}});
